        if current == goal:
            return path + [current]
        for next in set(graph[current]) - set(previous):
            previousCopy = previous.copy()
            previousCopy.add(next)
            result = dfs(graph, next, previousCopy, goal, path + [current])
            if result is not None:
                return result
        return None
    return dfs(graph, start, set(), goal, [start])
